igual('DRE ("292DRE03.2025.pdf"): REGISTRO DE LIVROS\\(001) ANO, nome original', so18(d18('292DRE03.2025.pdf', { texto: ['FITO INDUSTRIA E COMERCIO DE ALIMENTOS LTDA\nCNPJ 19.449.248/0001-62\nRECEITA BRUTA 1.000,00\nLUCRO LIQUIDO 100,00'] }, 'FERNANDO\\292 FITO INDUSTRIA E COMERCIO\\')), ['ARQUIVAR', null, '292 - FITO INDUSTRIA E COMERCIO DE ALIMENTOS LTDA\\CONTÁBIL\\REGISTRO DE LIVROS\\(001) 2025', '292DRE03.2025.pdf']);
igual('declaração de inventário (PDF) e balanço em planilha: PAPÉIS DE TRABALHO\\ANO', [d18('DECLARAÇÃO DE INVENTARIO 2023.pdf', { texto: ['DECLARACAO DE INVENTARIO\nDORNAS HAVANA LTDA CNPJ 01.884.649/0001-85\nESTOQUE EM 31/12/2023'] }, '0010 - DORNAS HAVANA LTDA - ME\\OUTROS\\').destinoRelativo, d18('BALANÇO 2021 - DORNAS HAVANA.xlsx', { planilha: [['ATIVO']] }, '0010 - DORNAS HAVANA LTDA - ME\\OUTROS\\').destinoRelativo], ['10 - DORNAS HAVANA LTDA - ME\\CONTÁBIL\\PAPÉIS DE TRABALHO\\2023', '10 - DORNAS HAVANA LTDA - ME\\CONTÁBIL\\PAPÉIS DE TRABALHO\\2021']);
